"""First actual Windows Selection parent inputs; finite, guarded, fresh each observation."""
from pathlib import Path
import argparse,json,hashlib
from driver import ps,q
r=Path(__file__).resolve().parents[2];p=argparse.ArgumentParser();p.add_argument('manifest',type=Path);p.add_argument('--after-mapping',action='store_true');a=p.parse_args();v=json.loads((a.manifest.parent/'windows-stage.json').read_text());assert v['owner']=='preflight'and v['component']=='selectionpage';assert json.loads((r/'docs/replica/ENVIRONMENT_LEASE.json').read_text())['resources']['windows']['owner']=='preflight';o=a.manifest.parent/'actual-windows-input';o.mkdir(exist_ok=True);cs=r/'tools/WindowsControl/owned_selection_page_input.cs';digest=hashlib.sha256(cs.read_bytes()).hexdigest();name='preflight-selection-input-'+digest+'.cs';(r/'artifacts/replica/windows-download'/name).write_bytes(cs.read_bytes());base="$app=Join-Path (Join-Path $env:TEMP "+q(v['guestFolder'])+") 'app';"
code=base+"$ProgressPreference='SilentlyContinue';$dll=Join-Path $app "+q('OwnedSelection-'+digest+'.dll')+";if(!(Test-Path $dll)){$cs=Join-Path $app 'owned-selection-input.cs';Invoke-WebRequest -UseBasicParsing "+q('http://10.211.55.2:8768/'+name)+" -OutFile $cs;if((Get-FileHash $cs -Algorithm SHA256).Hash-ne "+q(digest.upper())+"){throw 'Actor hash mismatch'};$rect=[System.Windows.Automation.AutomationElement]::RootElement.Current.BoundingRectangle;Add-Type -Path $cs -ReferencedAssemblies @('System.dll','System.Core.dll',$rect.GetType().Assembly.Location,[System.Windows.Automation.AutomationElement].Assembly.Location,[System.Windows.Automation.ControlType].Assembly.Location) -OutputAssembly $dll};Add-Type -Path $dll;"
code+=r'''function State($test){$limit=[DateTime]::UtcNow.AddSeconds(5);do{try{$f=[IO.File]::Open(($app+'\selectionpage-input.json'),[IO.FileMode]::Open,[IO.FileAccess]::Read,([IO.FileShare]::ReadWrite-bor[IO.FileShare]::Delete));$r=[IO.StreamReader]::new($f);try{$raw=$r.ReadToEnd()}finally{$r.Dispose()};$s=$raw|ConvertFrom-Json;if((& $test $s)){return $raw}}catch{};Start-Sleep -Milliseconds 50}while([DateTime]::UtcNow-lt$limit);throw 'Expected state absent; no input replay'};$checks=@();'''
steps=[('expand-data',"$s.selection.categories-contains'data'-and $s.categories[0].expanded"),('category-data',"$s.selection.categories-notcontains'data'-and $s.categories[0].expanded"),('scroll-table',None),('search-orders',"$s.selection.query-eq'orders'-and @($s.rows).Count-eq1-and @($s.selection.tables).Count-eq3"),('deselect',"$s.selection.tables-notcontains'demo.orders'-and @($s.selection.tables).Count-eq2"),('bulk',"$s.selection.tables-contains'demo.orders'-and @($s.selection.tables).Count-eq3"),('mapping',"@($s.requests).Count-eq1-and $s.requests[0]-eq'mapping:demo.orders'"),('clear-search',"$s.selection.query-eq''-and $s.searchFocused-and @($s.rows).Count-eq3"),('search-none',"$s.selection.query-eq'missing-table'-and $s.bulkCheckbox.disabled-and $s.deselect.disabled"),('empty-hover',"$s.empty[0].paint-eq'#ff3a3c44'"),('empty-leave',"$s.empty[0].paint-eq'Transparent'-or $s.empty[0].paint-eq'#00000000'"),('escape',"$s.selection.query-eq''-and $s.searchFocused"),('scroll-bottom',None),('passive',"!$s.searchFocused-and @($s.requests).Count-eq1"),('scroll-top',None),('category-trial',"$s.selection.categories-contains'trial'-and !$s.footer.enabled"),('scroll-bottom',None),('trial',"@($s.requests).Count-eq2-and $s.requests[1]-eq'trial'"),('scroll-top',None),('category-schema',"$s.selection.categories-notcontains'schema'-and $s.selection.categories-contains'trial'"),('focus-search',"$s.searchFocused"),('language',"$s.english-and $s.searchFocused-and $s.selection.query-eq''"),('mount',"!$s.attached"),('mount',"$s.attached-and @($s.selection.categories).Count-eq3"),('motion',None),('language',"!$s.english-and $s.attached"),('back',"@($s.requests).Count-eq3-and $s.requests[2]-eq'back'")]
if a.after_mapping:
 steps=steps[7:]
 steps=[(mode, expected.replace("@($s.requests).Count-eq1","@($s.requests).Count-eq0").replace("@($s.requests).Count-eq2-and $s.requests[1]","@($s.requests).Count-eq1-and $s.requests[0]").replace("@($s.requests).Count-eq3-and $s.requests[2]","@($s.requests).Count-eq2-and $s.requests[1]") if expected else None) for mode,expected in steps]
 # Fresh focus provider identity only, followed by previously unexecuted continuation.
 steps=[('scroll-table',None),('focus-mapping',"@($s.requests).Count-eq0")]+steps
for i,(mode,expected)in enumerate(steps):
 label=f'{i:02d}-{mode}';code+="$first=[OwnedSelectionPageInput]::Run($app,"+q(mode)+");$first|Set-Content -Encoding UTF8 ($app+'\\selection-first-"+label+".json');"
 if expected:code+="$raw=State {param($s) "+expected+"};$raw|Set-Content -Encoding UTF8 ($app+'\\selection-step-"+label+".json');$checks+=@{label="+q(label)+";passed=$true};"
code+="$checks|ConvertTo-Json;exit 0"
try:
 result=ps(code,timeout=60);(o/'batch-transport.txt').write_text(result);checks=json.loads(result);assert len(checks)==sum(x[1]is not None for x in steps);(o/'input-comparison.json').write_text(json.dumps(checks,indent=2));print('Windows finite checks '+str(len(checks)))
except Exception as e:
 (o/'batch-failure.txt').write_text(str(e));print('Finite failure saved; do not repeat uncertain input');raise SystemExit(1)
